 25	package hotel.reports;
 26	
 27	import hotel.reservations.Reservation;
 28	import hotel.reservations.ReservationStore;
 29	import java.math.BigDecimal;
 30	import java.time.YearMonth;
 31	import java.util.ArrayList;
 32	import java.util.Comparator;
 33	import java.util.List;
 34	
 35	/**
 36	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
 37	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
 38	 */
 39	public final class RevenueReport {
 40	
 41	    private final ReservationStore store;
 42	
 43	    public RevenueReport(ReservationStore store) {
 44	        this.store = store;
 45	    }
 46	
 47	    public String generate(YearMonth month) {
 48	        List<Reservation> withRevenue = new ArrayList<>();
 49	        for (Reservation reservation : store.all()) {
 50	            boolean keptMoney = reservation.amountKept().signum() > 0;
 51	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
 52	            if (keptMoney && startsInMonth) {
 53	                withRevenue.add(reservation);
 54	            }
 55	        }
 56	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
 57	
 58	        StringBuilder csv = new StringBuilder();
 59	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 60	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
 61	        for (Reservation reservation : withRevenue) {
 62	            csv.append(reservation.id()).append(',')
 63	                    .append(reservation.roomNumber()).append(',')
 64	                    .append(reservation.checkIn()).append(',')
 65	                    .append(reservation.checkOut()).append(',')
 66	                    .append(reservation.status()).append(',')
 67	                    .append(reservation.amountKept().toPlainString()).append('\n');
 68	            revenue = revenue.add(reservation.amountKept());
 69	        }
 70	        csv.append("total,").append(revenue.toPlainString()).append('\n');
 71	        return csv.toString();
 72	    }
 73	}
